"use strict";(()=>{const editable=e=>e.target instanceof Element&&!!e.target.closest('input,textarea,[contenteditable="true"],select');const stop=e=>{e.preventDefault();e.stopImmediatePropagation()};document.addEventListener('keydown',e=>{if(editable(e))return;const k=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(k==='f12'||mod&&['u','s'].includes(k)||mod&&e.shiftKey&&['i','j','c'].includes(k))stop(e)},true);document.addEventListener('selectstart',e=>{if(!editable(e))stop(e)},true);document.addEventListener('copy',e=>{if(!editable(e))stop(e)},true);document.addEventListener('dragstart',e=>{if(!editable(e))stop(e)},true)})();